func testOptionSetAlgebra() {
    let determined = HMHomeManagerAuthorizationStatus.determined
    let restricted = HMHomeManagerAuthorizationStatus.restricted
    let authorized = HMHomeManagerAuthorizationStatus.authorized
    hmRequire(determined.rawValue == 1, "determined")
    hmRequire(restricted.rawValue == 2, "restricted")
    hmRequire(authorized.rawValue == 4, "authorized")
    hmRequire(HMHomeManagerAuthorizationStatus(rawValue: 1) == determined, "init")
    let empty = HMHomeManagerAuthorizationStatus()
    hmRequire(empty.isEmpty, "empty")
    var status: HMHomeManagerAuthorizationStatus = [determined, restricted]
    hmRequire(status.contains(.determined), "contains determined")
    hmRequire(status.contains(.restricted), "contains restricted")
    hmRequire(!status.contains(.authorized), "not authorized")
    hmRequire(status.union(.authorized).contains(.authorized), "union")
    hmRequire(status.intersection(.restricted) == .restricted, "intersection")
    hmRequire(status.symmetricDifference(.restricted) == .determined, "symdiff")
    hmRequire(status.subtracting(.determined) == .restricted, "subtracting")
    hmRequire(status.isSuperset(of: .determined), "superset")
    hmRequire(determined.isSubset(of: status), "subset")
    hmRequire(determined.isDisjoint(with: .authorized), "disjoint")
    hmRequire(!determined.isStrictSubset(of: determined), "strict subset equal")
    hmRequire(determined.isStrictSubset(of: status), "strict subset")
    hmRequire(status.isStrictSuperset(of: .determined), "strict super")
    status.formUnion(.authorized)
    hmRequire(status.contains(.authorized), "formUnion")
    status.formIntersection(.authorized)
    hmRequire(status == .authorized, "formIntersection")
    status.formSymmetricDifference(.restricted)
    hmRequire(status.contains(.restricted) && status.contains(.authorized), "formSym")
    status.subtract(.authorized)
    hmRequire(status == .restricted, "subtract")
    var copy = status
    let inserted = copy.insert(.determined)
    hmRequire(inserted.inserted, "insert")
    hmRequire(copy.remove(.determined) != nil, "remove")
    hmRequire(copy.update(with: .authorized) == nil, "update")
    let fromSeq = HMHomeManagerAuthorizationStatus([determined, authorized])
    hmRequire(fromSeq.contains(.determined) && fromSeq.contains(.authorized), "seq")
    hmRequire(determined != restricted, "!=")
}

func testErrorOverlay() {
    let typed = HMError(.homeAccessNotAuthorized, userInfo: ["k": "v"])
    hmRequire(typed.code == .homeAccessNotAuthorized, "code")
    hmRequire(typed.errorCode == 47, "errorCode")
    hmRequire(HMError.errorDomain == HMErrorDomain, "domain")
    hmRequire(HMErrorDomain == "HMErrorDomain", "domain string")
    hmRequire(typed.userInfo["k"] as? String == "v", "userInfo")
    hmRequire(typed.errorUserInfo["k"] as? String == "v", "errorUserInfo")
    hmRequire(HMError.homeAccessNotAuthorized ~= typed, "~= typed")
    let ns = NSError(domain: HMErrorDomain, code: 47, userInfo: nil)
    hmRequire(HMError.homeAccessNotAuthorized ~= ns, "~= NSError")
    hmRequire((ns as? HMError) == nil, "fresh NSError is not HMError")
    hmRequire(typed == HMError(.homeAccessNotAuthorized, userInfo: ["k": "v"]), "==")
    hmRequire(typed != HMError(.notFound), "!=")
    var hasher = Hasher()
    typed.hash(into: &hasher)
    _ = hasher.finalize()
    _ = typed.hashValue
    hmRequire(HMError.Code.unexpectedError.rawValue == -1, "unexpected -1")
    hmRequire(HMError.Code(rawValue: 94) == nil, "gap 94")
}

